							dhcp: util.getValue(linesNicConfig, "dhcpEnabled", ":").toLowerCase() === "true",
							name: ifacename,
							iface,
							netEnabled: netEnabled === "TRUE",
							speed: isNaN(speed) ? null : speed,
							operstate: util.getValue(lines, "NetConnectionStatus", ":") === "2" ? "up" : "down",
							type: adapterType
