	function checkLinuxDCHPInterfaces(file, depth) {
		let result = [];
		depth = depth || 0;
		if (depth > 10) return result;
		try {
			readFileSync(file, { encoding: "utf8" }).split("\n").filter((l) => /iface|source/.test(l)).forEach((line) => {
				const parts = line.replace(/\s+/g, " ").trim().split(" ");
				if (parts.length >= 4) {
					if (line.toLowerCase().indexOf(" inet ") >= 0 && line.toLowerCase().indexOf("dhcp") >= 0) result.push(parts[1]);
				}
				if (line.toLowerCase().includes("source")) {
					const file = line.split(" ")[1];
					result = result.concat(checkLinuxDCHPInterfaces(file, depth + 1));
				}
			});
		} catch {
			util.noop();
		}
		return result;
	}
